using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading;
using System.Windows.Forms;

namespace AgitCon {
    static class ArcaTests {
        static int count;static void Check(bool value,string label){if(!value)throw new Exception(label);count++;}
        static void Reject(Action action,string label){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,label);}
        public static void Register(string id){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"register-arca.txt");try{var result=ArcaShop.Import(id,CancellationToken.None);var config=Catalog.Load();Catalog.MergePack(config,result);Catalog.Save(config);File.WriteAllText(report,"PASS: registered "+result.Pack.Id+" · "+result.Entries.Count+" image references, no bulk image download.\r\n");}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex.Message);Environment.ExitCode=1;}}
        public static void Run(bool live){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"arca-test-data",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);DcShop.CacheRoot=Path.Combine(root,"images");count=0;
            try{if(live){var pack=ArcaShop.Import("55611",CancellationToken.None);Check(pack.Entries.Count==42,"42 public image references");Check(pack.Pack.Id=="arca:55611","Arca provider namespace");Check(pack.Entries.All(e=>e.Path==null),"No eager local paths");Check(!Directory.Exists(DcShop.CacheRoot),"No images fetched during pack import");string image=DcShop.EnsureImage(pack.Entries[0],CancellationToken.None);Check(File.Exists(image),"Actual first image fetched");using(var bitmap=Image.FromFile(image))Check(bitmap.Width>0&&bitmap.Height>0,"Actual first image decodes");Check(Directory.GetFiles(DcShop.CacheRoot,"*",SearchOption.AllDirectories).Count(Catalog.Supported)==1,"Only selected image cached");
                    string raw=DcShop.EnsureAttachment(pack.Entries[0],CancellationToken.None);Check(Path.GetExtension(raw)==".webp"&&AssetCodec.Encoded(File.ReadAllBytes(raw)),"Original WebP used for attachment");Check(DcShop.EnsureAttachment(pack.Entries[0],CancellationToken.None,true)==image,"Compatible copy remains available separately");
                    Application.EnableVisualStyles();using(var form=new ShopForm(Catalog.Load().Packs,p=>{},e=>{},id=>{})){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();form.ShowArcaPreview(pack);for(int i=0;i<40;i++){Application.DoEvents();Thread.Sleep(25);}using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"arca-preview.png"));}form.ClientSize=new Size(454,540);Application.DoEvents();form.VerifyTabNavigation();}
                }else{Check(ArcaShop.PackId("https://arca.live/e/55611?p=1")=="55611","Query-safe pack link");Check(ArcaShop.PackId("arca:55611")=="55611","Namespaced identifier");Reject(()=>ArcaShop.PackId("https://evil.example/e/55611"),"Reject foreign pack host");Reject(()=>ArcaShop.PackId("http://arca.live/e/55611"),"HTTPS only");Reject(()=>ArcaShop.PackId("https://arca.live:8443/e/55611"),"Reject custom port");
                    byte[] json=File.ReadAllBytes(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","arca-pack-sample.json"));int metadata=0,images=0;byte[] png;using(var bitmap=new Bitmap(3,3))using(var stream=new MemoryStream()){bitmap.Save(stream,ImageFormat.Png);png=stream.ToArray();}
                    DcShop.TestTransport=(uri,body,token,limit,imageOnly)=>{if(imageOnly){images++;return png;}metadata++;return json;};var pack=ArcaShop.Import("55611",CancellationToken.None);Check(metadata==1&&images==0,"Import fetches metadata only");Check(pack.Entries.Count==42&&pack.Entries.All(e=>e.Path==null),"All references remain lazy");Check(pack.Pack.ThumbnailRemoteId==pack.Entries[0].RemoteId,"Refreshable thumbnail identity");
                    var config=new Settings();Catalog.MergePack(config,pack);int skipped;Check(Catalog.Scan(config,out skipped).Count==42,"Uncached Arca entries visible");config.Entries[0].Aliases="고맙, 감사";Catalog.MergePack(config,pack);Check(config.Entries.Count==42&&config.Packs.Count==1,"Reimport deduplicates");Check(config.Entries[0].Aliases=="고맙, 감사","User aliases preserved");config.Packs.Add(new PackRecord{Id="55611",Title="동일 번호 디시콘"});Check(config.Packs.Select(p=>p.Id).Distinct().Count()==2,"DC and Arca numbers cannot collide");
                    Entry first=pack.Entries[0];string identity=Catalog.Key(first),path=DcShop.EnsureImage(first,CancellationToken.None);Check(images==1&&File.Exists(path),"First image fetched lazily");first.SourceUrl="https://ac.arca.live/replaced.png?expires=0&key=changed";Check(Catalog.Key(first)==identity,"Signed URLs do not change identity");Check(DcShop.EnsureImage(first,CancellationToken.None)==path&&images==1,"Signed URL change reuses stable cache");
                    Check(DcShop.PersonalUrl("https://ac-p.namu.la/image.gif").Host=="ac-p.namu.la","Official image CDN accepted");Reject(()=>DcShop.PersonalUrl("https://ac-p.namu.la.evil.example/image.gif"),"CDN lookalike rejected");Reject(()=>DcShop.PersonalUrl("https://127.0.0.1/test.gif"),"Local network rejected");Check(ArcaShop.ImageUrl("//ac.arca.live/a.gif?type=webp&expires=123")=="https://ac.arca.live/a.gif?expires=123","Use original asset without thumbnail conversion");
                    string html="<html><meta property='og:url' content='https://arca.live/e/55611?p=1'><meta property='og:title' content='시험 팩 - 아카라이브'><img class='emoticon' data-id='1001' data-src='//ac.arca.live/first.png?type=webp' alt='감사'><video class='emoticon' data-id='1002'><source src='//ac.arca.live/second.mp4'></video><img src='https://ads.example/x.png'></html>";
                    var saved=ArcaShop.ParseSaved(html);Check(saved.Entries.Count==2,"Saved HTML reads only identified sticker media");Check(saved.Pack.Title=="시험 팩","Saved title parsed");Check(saved.Entries[0].Aliases=="감사"&&saved.Entries[1].Format=="mp4","Saved names and video metadata preserved");Reject(()=>ArcaShop.ParseSaved("<title>로그인 - 아카라이브</title>"),"Login page is not a pack");
                    var search=ArcaShop.ParseSearch("<a href='/e/55611?p=1'><img alt='시험 팩' src='//ac.arca.live/t.png'><span class='title'>시험 팩</span><span class='nickname'>제작자</span></a>");Check(search.Single().Id=="arca:55611"&&search[0].Seller=="제작자","Search parser provider and seller");
                    Catalog.DataPath=Path.Combine(root,"catalog.json");Catalog.Save(config);var restored=Catalog.Load();Check(restored.Entries[0].RemoteId==first.RemoteId&&restored.Entries[0].Aliases=="고맙, 감사","Stable identifiers and aliases persist");
                }File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,live?"arca-live-test.txt":"arca-test.txt"),"PASS: "+count+" Arca "+(live?"live API/image":"regression")+" checks. No KakaoTalk attachment test.\r\n");
            }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,live?"arca-live-test.txt":"arca-test.txt"),"FAIL: "+ex);Environment.ExitCode=1;}finally{DcShop.TestTransport=null;}
        }
    }
}
